const void *key = argkey;
    const void *data = argdata;
    size_t bucket = argbucket;
    size_t hashes[2];
    ckhc_t *cell;
    unsigned i;

    while (true) {
        // Choose a random item within the bucket to evict
        i = (unsigned)(ckh_prng(&ckh->prng_state) & ((ZU(1) << LG_CKH_BUCKET_CELLS) - 1));
        cell = &ckh->tab[(bucket << LG_CKH_BUCKET_CELLS) + i];

        // Swap cell's key/data with current key/data (evict)
        const void *tkey = cell->key;
        const void *tdata = cell->data;
        cell->key = key;
        cell->data = data;
        key = tkey;
        data = tdata;

        // Find the alternate bucket for the evicted item
        ckh->hash(key, hashes);
        size_t tbucket = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);

        if (tbucket == bucket) {
            tbucket = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
        }

        // Check for a cycle - if the evicted item wants to go back to argbucket
        if (tbucket == argbucket) {
            return true; // Failure - cycle detected
        }

        bucket = tbucket;

        // Try to insert the evicted item into its alternate bucket
        if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
            return false; // Success
        }
    }
